async function boot(){style();try{sb=window.supabase?.createClient?.(URL,KEY);if(!sb){let m=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.57.0/+esm');sb=m.createClient(URL,KEY)}let r=await sb.auth.getUser();user=r.data.user;if(!user){login();return}await load();shell();render();subscribe();registerSW()}catch(e){A.innerHTML='<div class="login"><div class="loginbox"><div class="hero"><small>WELLNESS TOUCH POINT</small><h1>Nikoleta Wellness CEO</h1><p>Παρουσιάστηκε σφάλμα φόρτωσης.</p></div><p class="muted">'+esc(e?.message||e)+'</p><button class="primary" style="width:100%" onclick="location.reload()">↻ Ανανέωση</button></div></div>'}}
function login(){A.innerHTML='<div class="login"><div class="loginbox"><div class="hero"><small>WELLNESS TOUCH POINT</small><h1>Nikoleta Wellness CEO</h1><p>Σύνδεση για να δεις τα δεδομένα σου.</p></div><form id="lf"><label>Email<input id="em" type="email" required></label><label>Κωδικός<input id="pw" type="password" required></label><button class="primary" style="width:100%">🔐 Σύνδεση</button></form><p id="msg" class="muted"></p><button id="sg" class="gold" style="width:100%">＋ Δημιουργία λογαριασμού</button></div></div>';lf.onsubmit=async e=>{e.preventDefault();msg.textContent='Σύνδεση…';let r=await sb.auth.signInWithPassword({email:em.value,password:pw.value});if(r.error)msg.textContent=r.error.message;else location.reload()};sg.onclick=async()=>{msg.textContent='Δημιουργία λογαριασμού…';let r=await sb.auth.signUp({email:em.value,password:pw.value});msg.textContent=r.error?r.error.message:'Ο λογαριασμός δημιουργήθηκε. Αν ζητηθεί, επιβεβαίωσε το email.'}}
async function ensureSession(){let q=await sb.auth.getSession();if(q.error)throw q.error;let session=q.data.session;if(!session)throw new Error('Η σύνδεση έληξε. Αποσυνδέσου και συνδέσου ξανά.');let iat=jwtIat(session.access_token),now=Math.floor(Date.now()/1000);if(iat>now+2){let rr=await sb.auth.refreshSession();if(rr.error)throw rr.error;session=rr.data.session;await waitForUsableJwt()}if(!session.expires_at||session.expires_at<=Math.floor(Date.now()/1000)+120){let rr=await sb.auth.refreshSession();if(rr.error)throw rr.error;session=rr.data.session;await waitForUsableJwt()}let check=await sb.auth.getUser();if(check.error){let rr=await sb.auth.refreshSession();if(rr.error)throw new Error('Αποτυχία ανανέωσης σύνδεσης: '+rr.error.message);session=rr.data.session;await waitForUsableJwt();check=await sb.auth.getUser();if(check.error)throw check.error}user=check.data.user||session.user;if(!user)throw new Error('Δεν βρέθηκε ενεργός χρήστης. Συνδέσου ξανά.');return user}
async function load(){await ensureSession();cache={};for(let [k,v] of Object.entries(F)){let r=await sb.from(v[2]).select('*').order('created_at',{ascending:false});if(r.error)console.warn('LOAD',k,r.error);cache[k]=r.data||[]}for(const [k,t] of [['programs','programs'],['client_trainings','client_trainings'],['wellness_visits','wellness_touch_points'],['communications','communication_history'],['partner_ranks','partner_rank_history']]){let r=await sb.from(t).select('*').order('created_at',{ascending:false});if(r.error)console.warn('LOAD',k,r.error);cache[k]=r.data||[]}}
let realtimeChannel=null;
function subscribe(){
  try{sb.removeAllChannels()}catch(e){}
  realtimeChannel=sb.channel('nikoleta-ceo-sync',{config:{broadcast:{self:false},presence:{key:user.id}}})
    .on('postgres_changes',{event:'*',schema:'public'},async()=>{try{await load();render()}catch(e){}})
    .subscribe(status=>{if(status==='CHANNEL_ERROR'||status==='TIMED_OUT'){setTimeout(()=>subscribe(),1500)}});
  document.addEventListener('visibilitychange',async()=>{if(document.visibilityState==='visible'){try{await load();render()}catch(e){}}});
  window.addEventListener('focus',async()=>{try{await load();render()}catch(e){}});
}
function shell(){A.innerHTML='<header class="top"><div class="brand"><small>WELLNESS TOUCH POINT</small><b>Nikoleta Wellness CEO</b></div><button class="menu" id="op">☰</button></header><aside class="drawer" id="dr"><h2>👑 CEO MENU</h2><button class="close" id="cl">× Κλείσιμο</button><button data-go="home">⌂ Αρχική</button>'+Object.entries(F).map(([k,v])=>`<button data-go="${k}">${v[0]} ${v[1]}</button>`).join('')+'<button id="notif">🔔 Ενεργοποίηση ειδοποιήσεων</button><button id="soundSettings">🎵 Ο προσωπικός μου ήχος</button><button id="lo">↪ Αποσύνδεση</button></aside><main id="view"></main><nav class="bottom"><button data-go="home"><span>⌂</span><small>Αρχική</small></button><button data-go="appointments"><span>📅</span><small>Ραντεβού</small></button><button data-go="clients"><span>👥</span><small>Πελάτες</small></button><button data-go="planner"><span>✓</span><small>Planner</small></button><button id="mo"><span>☰</span><small>Menu</small></button></nav>';op.onclick=()=>dr.classList.add('open');mo.onclick=()=>dr.classList.add('open');cl.onclick=()=>dr.classList.remove('open');lo.onclick=async()=>{await sb.auth.signOut();location.reload()};notif.onclick=async()=>{await registerPush(true);dr.classList.remove('open')};document.getElementById('soundSettings').onclick=()=>{dr.classList.remove('open');openSoundSettings()};document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{location.hash='#'+b.dataset.go;dr.classList.remove('open')});window.addEventListener('hashchange',render)}
function clientName(id,fallback){let c=(cache.clients||[]).find(x=>x.id===id);return c?.name||fallback||''}
async function resolveClientId(value){let name=String(value||'').trim();if(!name)return null;let found=(cache.clients||[]).find(x=>String(x.name||'').trim().toLowerCase()===name.toLowerCase());if(found)return found.id;await ensureSession();let r=await retryDataApi(()=>sb.from('clients').insert({user_id:user.id,name}).select('id,name').single());if(r.error){alert('Δεν μπόρεσα να αποθηκεύσω τον πελάτη: '+r.error.message);return null}cache.clients=[r.data,...(cache.clients||[])];return r.data.id}
const SAVE_FIELDS={followups:['client_id','title','follow_up_date','follow_up_time','status','reminder_minutes','notes'],finance:['client_id','transaction_date','transaction_type','category','description','amount','payment_method','notes'],orders:['client_id','order_date','product_name','quantity','unit_price','status','notes'],trips:['start_date','end_date','destination','trip_type','duration_days','company_trip','earned_trip','extravaganza','educational','notes'],inventory:['product_name','sku','category','stock','minimum_stock','unit_cost','unit_price','active','notes'],calendar:['title','event_type','event_date','start_time','end_time','client_id','notes','reminder_minutes','all_day']};
function cleanPayload(k,data){let out={};for(const key of (SAVE_FIELDS[k]||Object.keys(data)))if(Object.prototype.hasOwnProperty.call(data,key))out[key]=data[key];return out}
function jwtIat(token){try{let p=String(token||'').split('.')[1];if(!p)return 0;p=p.replace(/-/g,'+').replace(/_/g,'/');while(p.length%4)p+='=';return Number(JSON.parse(atob(p)).iat||0)}catch(e){return 0}}
async function waitForUsableJwt(){for(let i=0;i<12;i++){let s=(await sb.auth.getSession()).data.session;let iat=jwtIat(s?.access_token);let now=Math.floor(Date.now()/1000);if(!iat||iat<=now+2)return s;await new Promise(r=>setTimeout(r,Math.min(5000,Math.max(500,((iat-now)+2)*1000))))}return (await sb.auth.getSession()).data.session}
async function retryDataApi(fn){let r=await fn();if(!r?.error)return r;if(r.error.code==='PGRST303'||/jwt issued at future/i.test(r.error.message||'')){let rr=await sb.auth.refreshSession();if(!rr.error){user=rr.data.user||rr.data.session?.user||user;await waitForUsableJwt();r=await fn()}}return r}
async function cloudSave(k,id,data){await ensureSession();const table=F[k][2],payload=cleanPayload(k,data);return retryDataApi(()=>id?sb.from(table).update(payload).eq('id',id).eq('user_id',user.id).select().single():sb.from(table).insert({...payload,user_id:user.id}).select().single())}

function titleOf(k,o){if(k==='appointments'||k==='followups'||k==='orders'||k==='finance'||k==='calendar')return clientName(o.client_id,o.client_name)||o.title||o.description||o.product_name||o.destination||'Χωρίς πελάτη';if(k==='clients'||k==='partners')return o.name||'Χωρίς όνομα';if(k==='tanita')return clientName(o.client_id,'Μέτρηση Tanita');return o.title||o.product_name||o.destination||o.description||'Καταχώρηση'}
function details(k,o){if(k==='tanita')return `<div class="muted">${esc(o.measurement_date||'')} ${o.measurement_time?'• '+esc(tm(o.measurement_time)):''}</div><div class="muted">⚖️ Βάρος: ${esc(o.weight??'—')} kg • Λίπος: ${esc(o.body_fat??'—')}% • Μύες: ${esc(o.muscle_mass??'—')} kg</div><div class="muted">💧 Νερό: ${esc(o.water_percent??'—')}% • Οστική μάζα: ${esc(o.bone_mass??'—')} kg • Σπλαχνικό λίπος: ${esc(o.visceral_fat??'—')}</div><div class="muted">🔥 Tanita: ${esc(o.calories??'—')} kcal • Μεταβολική ηλικία: ${esc(o.metabolic_age??'—')} • Φυσική κατάσταση: ${esc(o.fitness_score??'—')}</div>${o.notes?`<div class="notice">📝 ${esc(o.notes)}</div>`:''}`;if(k==='finance')return `<div class="muted">${esc(o.transaction_date||'')} • ${esc(o.transaction_type||'')} • ${esc(o.amount??'')} €</div><div class="muted">${esc(o.description||'')}</div>${o.notes?`<div class="notice">📝 ${esc(o.notes)}</div>`:''}`;if(k==='followups')return `<div class="muted">${esc(o.follow_up_date||'')} ${o.follow_up_time?`• ${esc(tm(o.follow_up_time))}`:''} • ${esc(o.status||'')}</div>${o.notes?`<div class="notice">📝 ${esc(o.notes)}</div>`:''}`;if(k==='orders')return `<div class="muted">${esc(o.order_date||'')} • ${esc(o.product_name||'')} • ${esc(o.quantity??'')}</div>${o.notes?`<div class="notice">📝 ${esc(o.notes)}</div>`:''}`;if(k==='calendar')return `<div class="muted">${esc(o.event_date||'')} • ${esc(tm(o.start_time))}${o.end_time?`–${esc(tm(o.end_time))}`:''} • ${esc(o.event_type||'')}</div>${o.notes?`<div class="notice">📝 ${esc(o.notes)}</div>`:''}`;if(k==='appointments')return `<div class="muted"><b>${esc(o.title||'Ραντεβού')}</b> • ${esc(o.appointment_date||'')} • ${esc(tm(o.start_time))}${o.end_time?'–'+esc(tm(o.end_time)):''}</div><div class="muted">${esc(o.appointment_type||'')} ${o.status?'• '+esc(o.status):''}</div>${o.notes?`<div class="notice">📝 ${esc(o.notes)}</div>`:''}`;if(k==='clients')return `<div class="muted">${esc(o.phone||'')} ${o.email?'• '+esc(o.email):''}</div>${o.goal?`<div class="muted">🎯 ${esc(o.goal)}</div>`:''}${o.notes?`<div class="notice">📝 ${esc(o.notes)}</div>`:''}`;return o.notes?`<div class="notice">📝 ${esc(o.notes)}</div>`:''}
function formFields(k,o){return(SC[k]||[]).map(([n,l,t])=>{let v=o?.[n]??'';if(t==='client'){let current=clientName(v,'');return '<label>'+l+'<input type="text" name="'+n+'" data-client-input="1" list="nw-client-list" autocomplete="name" placeholder="Γράψε το όνομα του πελάτη" value="'+esc(current)+'"></label>'}if(t==='textarea')return '<label>'+l+'<textarea name="'+n+'">'+esc(v)+'</textarea></label>';if(t==='check')return '<label><input type="checkbox" name="'+n+'" '+(v?'checked':'')+'> '+l+'</label>';if(t==='time')return '<label>'+l+'<input name="'+n+'" type="time" value="'+esc(tm(v))+'"></label>';if(t.startsWith('select:'))return '<label>'+l+'<select name="'+n+'">'+t.slice(7).split(',').map(x=>'<option value="'+esc(x)+'" '+(String(v)===x?'selected':'')+'>'+esc(x)+'</option>').join('')+'</select></label>';return '<label>'+l+'<input name="'+n+'" type="'+t+'" value="'+esc(v)+'"></label>'}).join('')}
function installClientList(){let dl=document.getElementById('nw-client-list');if(!dl){dl=document.createElement('datalist');dl.id='nw-client-list';document.body.appendChild(dl)}dl.innerHTML=(cache.clients||[]).map(c=>'<option value="'+esc(c.name)+'"></option>').join('')}
function render(){let route=location.hash.slice(1)||'home';if(route.startsWith('client/'))return clientProfile(route.slice(7));if(route.startsWith('partner/'))return partnerProfile(route.slice(8));let k=route;if(!F[k])k='home';if(k==='home')return home();folder(k)}
let homeWeekOffset=0;
const dayNames=['ΔΕΥ','ΤΡΙ','ΤΕΤ','ΠΕΜ','ΠΑΡ','ΣΑΒ','ΚΥΡ'];
function localISO(d){let y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return y+'-'+m+'-'+day}
function mondayOfWeek(offset=0){let d=new Date();d.setHours(12,0,0,0);let n=(d.getDay()+6)%7;d.setDate(d.getDate()-n+(offset*7));return d}
function weekLabel(){let m=mondayOfWeek(homeWeekOffset),s=new Date(m);s.setDate(m.getDate()+6);return m.toLocaleDateString('el-GR',{day:'2-digit',month:'2-digit',year:'numeric'})+' – '+s.toLocaleDateString('el-GR',{day:'2-digit',month:'2-digit',year:'numeric'})}
function weeklyEvents(){let out=[];const push=(type,key,arr,dateField,timeField,titleFn)=>{(arr||[]).forEach(o=>{let d=o[dateField],t=o[timeField];if(d&&t)out.push({date:d,time:tm(t),title:titleFn(o),type,key,id:o.id})})};push('appointment','appointments',cache.appointments,'appointment_date','start_time',o=>'📅 '+(clientName(o.client_id,o.client_name)||o.title||'Ραντεβού'));push('planner','planner',cache.planner,'task_date','start_time',o=>'✓ '+(o.title||'Εργασία'));push('training','training',cache.training,'training_date','start_time',o=>'🎓 '+(o.title||'Εκπαίδευση'));push('followup','followups',cache.followups,'follow_up_date','follow_up_time',o=>'📞 '+(clientName(o.client_id)||o.title||'Follow-up'));push('calendar','calendar',cache.calendar,'event_date','start_time',o=>'🗓️ '+(clientName(o.client_id)||o.title||o.event_type||'Ημερολόγιο'));return out}
function weeklyPlan(){let d=new Date();d.setDate(d.getDate()+homeWeekOffset);let date=localISO(d),ev=weeklyEvents().filter(x=>x.date===date),hours=[];for(let h=0;h<=23;h++)hours.push(h);let label=d.toLocaleDateString('el-GR',{weekday:'long',day:'2-digit',month:'2-digit',year:'numeric'});return '<section class="weekly-wrap"><div class="weekly-head"><div><b>📅 ΗΜΕΡΗΣΙΟ ΗΜΕΡΟΛΟΓΙΟ</b><small>'+esc(label)+'</small></div><div class="weekly-nav"><button class="ghost" id="wprev">‹</button><button class="gold" id="wtoday">Σήμερα</button><button class="ghost" id="wnext">›</button></div></div><div class="weekly-scroll"><div class="weekly-grid" style="grid-template-columns:78px minmax(320px,1fr)"><div class="week-corner">ΩΡΑ</div><div class="week-day">'+esc(label)+'</div>'+hours.map(h=>'<div class="week-time">'+String(h).padStart(2,'0')+':00</div><div class="week-cell">'+ev.filter(x=>Number((x.time||'').slice(0,2))===h).map(x=>'<button type="button" class="week-event '+x.type+'" data-open-schedule="1" data-open-key="'+esc(x.key)+'" data-open-id="'+esc(x.id)+'">'+esc(x.title)+'</button>').join('')+'</div>').join('')+'</div></div><div class="weekly-legend"><span>📅 Ραντεβού</span><span>✓ Planner</span><span>🎓 Εκπαίδευση</span><span>📞 Follow-up</span><span>🗓️ Ημερολόγιο</span></div></section>'}

function home(){view.innerHTML=`<section class="page"><div class="hero"><small>WELLNESS BUSINESS SYSTEM</small><h1>Nikoleta Wellness CEO</h1><p>📅 ${new Date().toLocaleDateString('el-GR')} • ${esc(user.email)}</p></div><div class="bar"><h2>🌿 Οι φάκελοί μου</h2><button class="gold" onclick="location.hash='#appointments'">📅 Ραντεβού</button></div><div class="grid">${Object.entries(F).map(([k,v])=>`<button class="card" data-go="${k}"><b>${v[0]} ${v[1]}</b><small>${(cache[k]||[]).length} καταχωρήσεις</small></button>`).join('')}</div>${weeklyPlan()}<div class="notice">🔔 Για ειδοποιήσεις, πάτησε ☰ → «Ενεργοποίηση ειδοποιήσεων» σε κάθε συσκευή.</div></section>`;bindNav();view.querySelectorAll('[data-open-schedule]').forEach(b=>b.onclick=()=>edit(b.dataset.openKey,b.dataset.openId));document.getElementById('wprev').onclick=()=>{homeWeekOffset--;render()};document.getElementById('wnext').onclick=()=>{homeWeekOffset++;render()};document.getElementById('wtoday').onclick=()=>{homeWeekOffset=0;render()}}
function folder(k){let arr=cache[k]||[];let cards=arr.map(o=>`<article class="item"><b>${esc(titleOf(k,o))}</b>${details(k,o)}<div class="actions">${k==='clients'?`<button class="primary" data-profile="${o.id}">📁 Άνοιγμα φακέλου</button>`:k==='partners'?`<button class="primary" data-partner-profile="${o.id}">📁 Άνοιγμα φακέλου</button>`:''}<button class="primary" data-edit="${o.id}">✏️ Επεξεργασία</button>${k==='tanita'?'':`<button class="gold" data-rem="${o.id}">🔔 Ειδοποίηση</button>`}<button class="danger" data-del="${o.id}">🗑️ Διαγραφή</button></div></article>`).join('');view.innerHTML=`<section class="page"><div class="hero"><small>${F[k][1].toUpperCase()}</small><h1>${F[k][0]} ${F[k][1]}</h1><p>${k==='appointments'?'Κάθε καρτέλα δείχνει ονοματεπώνυμο πελάτη και η Επεξεργασία ανοίγει με όλα τα ήδη αποθηκευμένα πεδία και σημειώσεις.':'Όλες οι καταχωρήσεις παραμένουν συγχρονισμένες.'}</p></div><div class="bar"><button class="primary" id="add">＋ Νέα εγγραφή</button><button class="gold" id="nall">🔔 Νέα υπενθύμιση</button></div><div class="list">${cards||'<div class="empty">Δεν υπάρχουν ακόμη καταχωρήσεις.</div>'}</div></section>`;bindNav();add.onclick=()=>edit(k,null);nall.onclick=()=>reminder(k,null);view.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>{location.hash='#client/'+b.dataset.profile});view.querySelectorAll('[data-partner-profile]').forEach(b=>b.onclick=()=>{location.hash='#partner/'+b.dataset.partnerProfile});view.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(k,b.dataset.edit));view.querySelectorAll('[data-rem]').forEach(b=>b.onclick=()=>reminder(k,b.dataset.rem));view.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>del(k,b.dataset.del))}
function clientProfile(id){const c=(cache.clients||[]).find(x=>x.id===id);if(!c){location.hash='#clients';return}const related=key=>(cache[key]||[]).filter(x=>x.client_id===id);const rows=(key,label,sub)=>{let a=related(key);return '<section class="item"><div class="head"><b>'+label+'</b><span class="muted">'+a.length+' καταχωρήσεις</span></div>'+(a.length?a.map(o=>'<div class="notice"><b>'+esc(sub(o))+'</b><div class="muted">'+esc(o.measurement_date||o.appointment_date||o.follow_up_date||o.order_date||o.transaction_date||o.event_date||o.start_date||o.check_in_at||o.training_date||'')+(o.start_time?' • '+esc(tm(o.start_time)):'')+'</div>'+(o.notes?'<div class="muted">📝 '+esc(o.notes)+'</div>':'')+'</div>').join(''):'<p class="muted">Δεν υπάρχουν ακόμη καταχωρήσεις.</p>')+'</section>'};view.innerHTML='<section class="page"><div class="hero"><small>ΠΡΟΣΩΠΙΚΟΣ ΦΑΚΕΛΟΣ ΠΕΛΑΤΗ</small><h1>👤 '+esc(c.name)+'</h1><p>'+esc(c.phone||'Χωρίς τηλέφωνο')+' • '+esc(c.email||'Χωρίς email')+'</p><p>🎯 '+esc(c.goal||'Δεν έχει καταχωρηθεί στόχος')+' • '+esc(c.status||'')+'</p></div><div class="bar"><button class="ghost" id="backClients">← Πελάτες</button><button class="primary" id="editClient">✏️ Στοιχεία πελάτη</button></div><div class="grid"><article class="item"><b>📋 Προσωπικά στοιχεία</b><div class="muted">Διεύθυνση: '+esc(c.address||'—')+'</div><div class="muted">Περιοχή: '+esc(c.area||'—')+'</div><div class="muted">Ημ. γέννησης: '+esc(c.birth_date||'—')+'</div><div class="muted">Έναρξη: '+esc(c.start_date||'—')+'</div><div class="muted">Επόμενη μέτρηση: '+esc(c.next_measurement_date||'—')+'</div>'+(c.notes?'<div class="notice">📝 '+esc(c.notes)+'</div>':'')+'</article><article class="item"><b>📊 Σύνοψη φακέλου</b><div class="muted">⚖️ Μετρήσεις Tanita: '+related('tanita').length+'</div><div class="muted">📅 Ραντεβού: '+related('appointments').length+'</div><div class="muted">📞 Follow-ups: '+related('followups').length+'</div><div class="muted">🛒 Παραγγελίες: '+related('orders').length+'</div><div class="muted">💰 Οικονομικές εγγραφές: '+related('finance').length+'</div></article></div><div class="bar"><h2>Γρήγορες ενέργειες</h2></div><div class="actions"><button class="primary" id="newAppointment">＋ Ραντεβού</button><button class="gold" id="newTanita">＋ Μέτρηση Tanita</button><button class="ghost" id="newFollowup">＋ Follow-up</button></div><div class="bar"><h2>Ιστορικό πελάτη</h2></div>'+rows('tanita','⚖️ Ιστορικό μετρήσεων',o=>'Μέτρηση Tanita — '+(o.weight??'—')+' kg')+rows('appointments','📅 Ραντεβού',o=>o.title||'Ραντεβού')+rows('followups','📞 Follow-ups',o=>o.title||'Επικοινωνία')+rows('orders','🛒 Παραγγελίες',o=>o.product_name||'Παραγγελία')+rows('finance','💰 Οικονομικές εγγραφές',o=>(o.transaction_type==='income'?'Έσοδο':'Έξοδο')+' — '+(o.amount??'')+' €')+rows('calendar','🗓️ Ημερολόγιο',o=>o.title||o.event_type||'Καταχώρηση')+rows('programs','🥗 Διατροφικά προγράμματα',o=>o.title||'Πρόγραμμα')+rows('client_trainings','🎓 Εκπαιδεύσεις πελάτη',o=>o.title||'Εκπαίδευση')+rows('wellness_visits','🌿 Επισκέψεις Wellness',o=>o.consumed||'Επίσκεψη')+rows('communications','💬 Ιστορικό επικοινωνίας',o=>o.title||o.communication_type||'Επικοινωνία')+'</section>';document.getElementById('backClients').onclick=()=>location.hash='#clients';document.getElementById('editClient').onclick=()=>edit('clients',id);document.getElementById('newAppointment').onclick=()=>edit('appointments',null,{client_id:id});document.getElementById('newTanita').onclick=()=>edit('tanita',null,{client_id:id});document.getElementById('newFollowup').onclick=()=>edit('followups',null,{client_id:id})}
function partnerRankDates(partnerId,ranks){const latest={};for(const r of ranks){if(!latest[r.rank_name]||(r.qualification_date||'')>(latest[r.rank_name].qualification_date||''))latest[r.rank_name]=r}return '<section class="item" id="rankDatePanel"><b>🗓️ Ημερομηνία πρόκρισης για κάθε βαθμίδα</b><p class="muted">Συμπλήρωσε ξεχωριστά την ημερομηνία δίπλα σε κάθε βαθμίδα που έχει προκριθεί ο συνεργάτης.</p>'+RANKS.map((name,i)=>'<div class="grid" style="align-items:center;border-bottom:1px solid var(--line);padding:8px 0"><label style="margin:0">'+(i+1)+'. '+esc(name)+'</label><input type="date" data-rank-date="'+esc(name)+'" aria-label="Ημερομηνία πρόκρισης '+esc(name)+'" value="'+esc(latest[name]?.qualification_date||'')+'"></div>').join('')+'<button class="primary" id="saveAllRankDates" style="width:100%;margin-top:12px">💾 Αποθήκευση όλων των ημερομηνιών</button></section>'}
async function savePartnerRankDates(partnerId){const panel=document.getElementById('rankDatePanel');const inputs=[...panel.querySelectorAll('[data-rank-date]')];for(const input of inputs){const name=input.dataset.rankDate,date=input.value;if(!date)continue;const existing=(cache.partner_ranks||[]).filter(r=>r.partner_id===partnerId&&r.rank_name===name).sort((a,b)=>(b.qualification_date||'').localeCompare(a.qualification_date||''))[0];const data={partner_id:partnerId,rank_name:name,qualification_date:date,user_id:user.id};const result=existing?await sb.from('partner_rank_history').update(data).eq('id',existing.id).eq('user_id',user.id):await sb.from('partner_rank_history').insert(data);if(result.error){alert('Δεν αποθηκεύτηκε η ημερομηνία για '+name+': '+result.error.message);return}}await load();partnerProfile(partnerId);alert('Οι ημερομηνίες προκρίσεων αποθηκεύτηκαν.')}
function partnerProfile(id){const p=(cache.partners||[]).find(x=>x.id===id);if(!p){location.hash='#partners';return}const ranks=(cache.partner_ranks||[]).filter(x=>x.partner_id===id).sort((a,b)=>(b.qualification_date||'').localeCompare(a.qualification_date||''));const events=(cache.calendar||[]).filter(x=>x.partner_id===id);view.innerHTML='<section class="page"><div class="hero"><small>ΠΡΟΣΩΠΙΚΟΣ ΦΑΚΕΛΟΣ ΣΥΝΕΡΓΑΤΗ</small><h1>🤝 '+esc(p.name)+'</h1><p>Herbalife ID: '+esc(p.id_number||'—')+'</p><p>Βαθμίδα: '+esc(p.current_rank||'—')+' • Κατάσταση: '+esc(p.status||'')+'</p></div><div class="bar"><button class="ghost" id="backPartners">← Συνεργάτες</button><button class="primary" id="editPartner">✏️ Στοιχεία συνεργάτη</button></div><div class="grid"><article class="item"><b>📋 Προσωπικά στοιχεία</b><div class="muted">Τηλέφωνο: '+esc(p.phone||'—')+'</div><div class="muted">Email: '+esc(p.email||'—')+'</div><div class="muted">Ημερομηνία εγγραφής: '+esc(p.registration_date||'—')+'</div><div class="muted">Herbalife ID: '+esc(p.id_number||'—')+'</div></article><article class="item"><b>🏆 Επαγγελματική πορεία</b><div class="muted">Τρέχουσα βαθμίδα: '+esc(p.current_rank||'—')+'</div><div class="muted">Τελευταία πρόκριση: '+esc(p.rank_qualification_date||'—')+'</div><div class="muted">Επόμενη βαθμίδα: '+esc(p.next_rank||'—')+'</div><div class="muted">Προκρίσεις: '+ranks.length+'</div></article></div><div class="bar"><h2>Γρήγορες ενέργειες</h2><button class="gold" id="addRank">＋ Καταχώριση πρόκρισης</button></div><section class="item"><b>🎯 Στόχοι και ενέργειες</b><div class="notice">'+esc(p.goals||'Δεν έχουν καταχωρηθεί στόχοι')+'</div><div class="notice">'+esc(p.actions||'Δεν έχουν καταχωρηθεί ενέργειες')+'</div></section><section class="item"><b>🏅 Ιστορικό βαθμίδων και προκρίσεων</b>'+(ranks.length?ranks.map(r=>'<div class="notice"><b>'+esc(r.rank_name)+'</b><div class="muted">Πρόκριση: '+esc(r.qualification_date)+' • Επιβεβαίωση: '+esc(r.confirmed_date||'—')+'</div>'+(r.notes?'<div class="muted">📝 '+esc(r.notes)+'</div>':'')+'<div class="actions"><button class="primary" data-rank-edit="'+r.id+'">✏️ Επεξεργασία</button><button class="danger" data-rank-del="'+r.id+'">🗑️ Διαγραφή</button></div></div>').join(''):'<p class="muted">Δεν έχουν καταχωρηθεί προκρίσεις.</p>')+'</section><section class="item"><b>🗓️ Συναντήσεις</b>'+(events.length?events.map(e=>'<div class="notice"><b>'+esc(e.title||e.event_type||'Συνάντηση')+'</b><div class="muted">'+esc(e.event_date||'')+' '+esc(e.start_time||'')+'</div></div>').join(''):'<p class="muted">Δεν υπάρχουν συνδεδεμένες συναντήσεις.</p>')+'</section><section class="item"><b>📝 Σημειώσεις</b><p>'+esc(p.notes||'—')+'</p></section></section>';view.insertAdjacentHTML('afterbegin',partnerRankDates(id,ranks));document.getElementById('saveAllRankDates').onclick=()=>savePartnerRankDates(id);document.getElementById('backPartners').onclick=()=>location.hash='#partners';document.getElementById('editPartner').onclick=()=>edit('partners',id);document.getElementById('addRank').onclick=()=>rankEditor(id,null);view.querySelectorAll('[data-rank-edit]').forEach(b=>b.onclick=()=>rankEditor(id,b.dataset.rankEdit));view.querySelectorAll('[data-rank-del]').forEach(b=>b.onclick=async()=>{if(!confirm('Να διαγραφεί η πρόκριση;'))return;const r=await sb.from('partner_rank_history').delete().eq('id',b.dataset.rankDel).eq('user_id',user.id);if(r.error){alert(r.error.message);return}await load();partnerProfile(id)})}
function rankEditor(partnerId,rankId){const old=rankId?(cache.partner_ranks||[]).find(x=>x.id===rankId)||{}:{};const d=modal('<div class="head"><h2>🏅 '+(rankId?'Επεξεργασία':'Νέα')+' πρόκρισης</h2><button class="x">×</button></div><form id="rankForm"><div class="grid"><label>Βαθμίδα<select name="rank_name" required>'+(RANKS.includes(old.rank_name)?'':'<option value="'+esc(old.rank_name||'')+'" selected>'+esc(old.rank_name||'Επίλεξε βαθμίδα')+'</option>')+RANKS.map(x=>'<option value="'+esc(x)+'" '+(old.rank_name===x?'selected':'')+' >'+esc(x)+'</option>').join('')+'</select></label><label>Ημερομηνία πρόκρισης<input name="qualification_date" type="date" required value="'+esc(old.qualification_date||today())+'"></label></div><label>Ημερομηνία επιβεβαίωσης<input name="confirmed_date" type="date" value="'+esc(old.confirmed_date||'')+'"></label><label>Σημειώσεις<textarea name="notes">'+esc(old.notes||'')+'</textarea></label><button class="primary" style="width:100%">💾 Αποθήκευση</button></form>');d.querySelector('.x').onclick=()=>d.remove();d.querySelector('#rankForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);const data={partner_id:partnerId,rank_name:fd.get('rank_name').trim(),qualification_date:fd.get('qualification_date'),confirmed_date:fd.get('confirmed_date')||null,notes:fd.get('notes')||null,user_id:user.id};const r=rankId?await sb.from('partner_rank_history').update(data).eq('id',rankId).eq('user_id',user.id):await sb.from('partner_rank_history').insert(data);if(r.error){alert('Δεν αποθηκεύτηκε: '+r.error.message);return}if(!rankId)await sb.from('partners').update({current_rank:data.rank_name,rank_qualification_date:data.qualification_date}).eq('id',partnerId).eq('user_id',user.id);d.remove();await load();partnerProfile(partnerId)}}
